<?php
namespace App\Http\Controllers\api;
use App\Http\Controllers\Controller; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class TeacherAssignmentMobileApiController extends Controller { public function standards(Request $r){$teacher=(int)$r->session()->get('user_id');$institute=(int)$r->session()->get('sub_institute_id');abort_if(!$teacher||!$institute,401);return response()->json(['status'=>1,'data'=>DB::table('timetable as t')->join('standard as s','s.id','=','t.standard_id')->where('t.teacher_id',$teacher)->where('t.sub_institute_id',$institute)->selectRaw('distinct t.standard_id as id,s.name as name')->get()]);} public function divisions(Request $r){$r->validate(['standard_id'=>'required|integer']);$teacher=(int)$r->session()->get('user_id');$institute=(int)$r->session()->get('sub_institute_id');abort_if(!$teacher||!$institute,401);return response()->json(['status'=>1,'data'=>DB::table('timetable as t')->join('division as d','d.id','=','t.division_id')->where('t.teacher_id',$teacher)->where('t.sub_institute_id',$institute)->where('t.standard_id',$r->integer('standard_id'))->selectRaw('distinct t.division_id as id,d.name as name')->get()]);}}
